// A small seeded random generator (mulberry32): the same seed gives the same island, which is
// what makes the screenshot scenes repeatable.

export function createRandom(seed) {
  let a = seed | 0;
  return function random() {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Pick an integer in [min, max] from a random function. */
export function intBetween(random, min, max) {
  return min + Math.floor(random() * (max - min + 1));
}

/** Pick one element of an array. */
export function pick(random, array) {
  return array[Math.floor(random() * array.length)];
}
